[CmdletBinding()]param([switch]$NoGodot,[switch]$Editor)
$ErrorActionPreference='Stop';$root=$PSScriptRoot
& (Join-Path $root 'Start-InferenceService.ps1')
$cfg=Get-Content -Raw (Join-Path $root 'bridge_config.json')|ConvertFrom-Json
try{Invoke-RestMethod "http://$($cfg.host):$($cfg.port)/health" -TimeoutSec 1|Out-Null;Write-Host 'Game bridge already running.'}catch{$stdout=Join-Path $root 'eval/.work/game-bridge.stdout.log';$stderr=Join-Path $root 'eval/.work/game-bridge.stderr.log';Start-Process -FilePath (Get-Command pwsh).Source -ArgumentList @('-NoProfile','-File',(Join-Path $root 'Start-GameBridge.ps1')) -WorkingDirectory $root -RedirectStandardOutput $stdout -RedirectStandardError $stderr -WindowStyle Hidden|Out-Null;$ready=$false;1..40|ForEach-Object{if(-not$ready){Start-Sleep -Milliseconds 250;try{Invoke-RestMethod "http://$($cfg.host):$($cfg.port)/health" -TimeoutSec 1|Out-Null;$ready=$true}catch{}}};if(-not$ready){throw "Game bridge did not start. See $stderr"};Write-Host "Game bridge ready at http://$($cfg.host):$($cfg.port)."}
if(-not$NoGodot){$godot=Get-ChildItem (Join-Path $root '.runtime/godot') -Filter 'Godot_v4.7.2-stable_win64.exe'|Select-Object -First 1;if(-not$godot){throw 'Project-local Godot 4.7.2 executable is missing.'};$godotArgs=@('--path',(Join-Path $root 'godot'));if($Editor){$godotArgs+='--editor'};Start-Process -FilePath $godot.FullName -ArgumentList $godotArgs -WorkingDirectory (Join-Path $root 'godot')|Out-Null;Write-Host $(if($Editor){'Godot editor launched. Press F6/F5 to play.'}else{'Callum Study prototype launched.'})}
